// Gaussian convolution of native scalar fields. Reflect at physical edges;
// zero-pad the FFT convolution so no spectral or range wrapping is introduced.
use std::sync::Arc;
use rustfft::{Fft,FftPlanner,num_complex::Complex64};
pub struct Gaussian{n:usize,pad:usize,forward:Arc<dyn Fft<f64>>,inverse:Arc<dyn Fft<f64>>,kernel:Vec<Complex64>,work:Vec<Complex64>,scratch:Vec<Complex64>}
impl Gaussian{
 pub fn new(n:usize,sigma:f64)->Self{assert!(n>1&&sigma>0.);let pad=(4.*sigma).ceil()as usize;let size=(n+4*pad).next_power_of_two();let mut planner=FftPlanner::new();let forward=planner.plan_fft_forward(size);let inverse=planner.plan_fft_inverse(size);let mut kernel=vec![Complex64::default();size];let mut sum=0.;for i in 0..=2*pad{let x=(i as f64-pad as f64)/sigma;let w=(-0.5*x*x).exp();kernel[i].re=w;sum+=w;}for v in &mut kernel{v.re/=sum;}forward.process(&mut kernel);let scratch=vec![Complex64::default();forward.get_inplace_scratch_len().max(inverse.get_inplace_scratch_len())];Self{n,pad,forward,inverse,kernel,work:vec![Complex64::default();size],scratch}}
 pub fn smooth(&mut self,input:&[f64],output:&mut[f64]){assert_eq!(input.len(),self.n);assert_eq!(output.len(),self.n);self.work.fill(Complex64::default());for j in 0..self.n+2*self.pad{let mut k=j as isize-self.pad as isize;while k<0||k>=self.n as isize{k=if k<0{-k-1}else{2*self.n as isize-k-1};}self.work[j].re=input[k as usize];}self.forward.process_with_scratch(&mut self.work,&mut self.scratch);for(v,k)in self.work.iter_mut().zip(&self.kernel){*v*=k;}self.inverse.process_with_scratch(&mut self.work,&mut self.scratch);let norm=self.work.len()as f64;for(i,v)in output.iter_mut().enumerate(){*v=self.work[i+2*self.pad].re/norm;}}
}
pub fn highpass_2d(field:&[f64],nx:usize,sigma:f64)->Vec<f64>{highpass_axes(field,nx,sigma,sigma)}
pub fn highpass_axes(field:&[f64],nx:usize,sigma_x:f64,sigma_y:f64)->Vec<f64>{assert_eq!(field.len()%nx,0);let ny=field.len()/nx;let first=field.chunks_exact(nx).position(|r|r.iter().all(|x|x.is_finite())).expect("no finite ranges");assert!(field[first*nx..].iter().all(|x|x.is_finite()),"interior missing samples need explicit weighted convolution");let mut horizontal=vec![0.;(ny-first)*nx];let mut gx=Gaussian::new(nx,sigma_x);for(src,dst)in field[first*nx..].chunks_exact(nx).zip(horizontal.chunks_exact_mut(nx)){gx.smooth(src,dst);}let mut gy=Gaussian::new(ny-first,sigma_y);let mut column=vec![0.;ny-first];let mut smooth=column.clone();let mut residual=vec![f64::NAN;field.len()];for x in 0..nx{for y in 0..ny-first{column[y]=horizontal[y*nx+x];}gy.smooth(&column,&mut smooth);for y in 0..ny-first{let j=(y+first)*nx+x;residual[j]=field[j]-smooth[y];}}residual}
#[cfg(test)]mod tests{use super::*;
 #[test]fn constant_survives_at_edges(){let mut g=Gaussian::new(1024,50.);let mut out=vec![0.;1024];g.smooth(&vec![3.;1024],&mut out);assert!(out.iter().all(|v|(v-3.).abs()<1e-12));}
 #[test]fn preserve_narrow_line_remove_broad_background(){let n=2048;let mut g=Gaussian::new(n,50.);let ridge:Vec<_>=(0..n).map(|i|(-0.5*((i as f64-1024.)/1.).powi(2)).exp()).collect();let broad:Vec<_>=(0..n).map(|i|(-0.5*((i as f64-1024.)/250.).powi(2)).exp()).collect();let mut s=vec![0.;n];g.smooth(&ridge,&mut s);assert!(ridge[1024]-s[1024]>0.97);g.smooth(&broad,&mut s);assert!(broad[1024]-s[1024]<0.03);}
}
